#!/bin/bash
#SBATCH --job-name=ichor_pon
#SBATCH --time=03:00:00
#SBATCH --cpus-per-task=4
#SBATCH --mem=26214MB
#SBATCH --mail-type=END
#SBATCH --output=logs/%j_ichor_pon.out
#SBATCH --error=logs/%j_ichor_pon.out

# ============================================================================
# Build the ichorCNA panel of normals from the 50 held-out Cristiano samples
# ============================================================================
# Inputs: input/cris_pon_wigs.txt — the 50 panel wig paths, generated by
#   python src/comp/build_cris_manifest.py
# (50 plasma-cfDNA samples from 50 distinct healthy individuals — one base
# sequencing run each, no replicates; the two lymphocyte gDNA samples
# CGH14/CGH15 are excluded by construction.)
#
# Output: results/ichorCNA_pon/pon_cris50_median.rds, the --normalPanel of
# runIchorCNA.R (settings in README.md, section 6). Uses the hg38 1 Mb
# gc/map/centromere references of the ichorCNA checkout. Submit from the
# repository root.
# ============================================================================

. slurm/_site.sh   # site settings: slurm/site.env (scheduler, storage paths, container, Apptainer cache)
TOOLS=${ICHORCNA_DIR}
WIG_LIST=input/cris_pon_wigs.txt
OUT_DIR=results/ichorCNA_pon
OUT_PREFIX=${OUT_DIR}/pon_cris50

set -e

# Preflight: the active R environment must provide ichorCNA and its
# dependencies. NOTE: bioconda's r-ichorcna now resolves to 0.5.1 while the
# scripts used here come from the 0.3.2 checkout at ${TOOLS} — after creating
# the conda env, install the checkout over it to pin 0.3.2:
#   conda activate <your ichorCNA conda env>
#   R CMD INSTALL ${TOOLS}
# sbatch inherits the submission shell's environment, so submit from the
# activated env. The version is echoed below for the log.
if ! Rscript -e 'suppressMessages({library(optparse); library(HMMcopy); library(GenomicRanges); library(ichorCNA)})' 2>/dev/null; then
    echo "ERROR: this R environment cannot load optparse/HMMcopy/GenomicRanges/ichorCNA."
    echo "Create the env (compute node for the solve, login node for the linking; see"
    echo "envs/ichor), activate it, R CMD INSTALL ${TOOLS}, then resubmit."
    exit 1
fi
echo "ichorCNA version in this environment: $(Rscript -e 'cat(as.character(packageVersion("ichorCNA")))' 2>/dev/null) (0.3.2 = the checkout these scripts expect)"

if [ ! -s "${WIG_LIST}" ]; then
    echo "ERROR: ${WIG_LIST} not found or empty — run: python src/comp/build_cris_manifest.py"
    exit 1
fi

N_WIGS=$(wc -l < "${WIG_LIST}")
echo "============================================"
echo "ichorCNA panel of normals"
echo "  wig list : ${WIG_LIST} (${N_WIGS} samples)"
echo "  output   : ${OUT_PREFIX}_median.rds"
echo "============================================"

MISSING=0
while read -r w; do
    [ -f "$w" ] || { echo "  MISSING WIG: $w"; MISSING=$((MISSING+1)); }
done < "${WIG_LIST}"
if [ "${MISSING}" -gt 0 ]; then
    echo "ERROR: ${MISSING} wig file(s) missing — aborting."
    exit 1
fi

mkdir -p "${OUT_DIR}"

Rscript "${TOOLS}/scripts/createPanelOfNormals.R" \
    --filelist "${WIG_LIST}" \
    --gcWig "${TOOLS}/inst/extdata/gc_hg38_1000kb.wig" \
    --mapWig "${TOOLS}/inst/extdata/map_hg38_1000kb.wig" \
    --centromere "${TOOLS}/inst/extdata/GRCh38.GCA_000001405.2_centromere_acen.txt" \
    --outfile "${OUT_PREFIX}"

echo ""
if [ -f "${OUT_PREFIX}_median.rds" ]; then
    echo "OK panel written: ${OUT_PREFIX}_median.rds"
    echo "Next: run ichorCNA with --normalPanel ${OUT_PREFIX}_median.rds (README.md, section 6)."
else
    echo "ERROR: expected output ${OUT_PREFIX}_median.rds not found."
    exit 1
fi
